// #45f435 (6a993d743e771e2d8145f435) «פיתוח: ניהול מחזור חיי קישור המועמד» — business в «ניהול הקישור»: отмена, продление
// после отмены, новая ссылка; кандидат (гость) видит S-11 на старой ссылке и приветствие на новой; подделанный токен.
// Кейсы LINK-001…LINK-004. Две роли (business + гость) — записано autotest-writer вручную.
// НЕ prod-safe (кроме теста подделанного токена): каждый тест создаёт своего кандидата «QA-AUTO-45f435-…» (link_only)
// и действует только на него. Ничего не удаляется (правило проекта 13.10). Попытки кандидата не начинаются.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, candidateRow } from '../candidate-call/support';
import { S11, candidateId, openManage, confirmAction, linkIn, expectInactive, expectWelcome } from './support';

const HASH = '#45f435';

test.describe(`Ссылка кандидата — отмена, продление, новая ссылка (${HASH})`, () => {
  test(`отмена: cancel_candidate_link 200 status=cancelled, «הקישור בוטל», статус «בוטל»; кандидат — S-11 «הקישור לא פעיל» с путём к команде; в списке «בוטל» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(3 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-45f435-C-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: ссылка отменена, не удаляется` });
    const id = await candidateId(business, name);

    const panel = await openManage(business, id);
    expect(new URL(await linkIn(panel)).pathname, 'в окне — та же ссылка, что выдана при создании').toBe(new URL(link).pathname);
    await panel.getByRole('button', { name: 'ביטול הקישור', exact: true }).click();
    const res = await confirmAction(business, 'ביטול הקישור', /\/rpc\/cancel_candidate_link/);
    // Источник: AC2 — «הוא מפסיק לפעול מיידית והסטטוס עובר לבוטל».
    expect(JSON.stringify(await res.json())).toContain('"cancelled"');
    await expect(panel.getByText('הקישור בוטל').first()).toBeVisible();
    await expect(panel.getByText(`הקישור של ${name} הפסיק לפעול.`)).toBeVisible();
    await expect(panel.getByText('בוטל', { exact: true }).first()).toBeVisible();
    await expect(panel.getByRole('button', { name: 'הארכת תוקף', exact: true })).toBeVisible();
    await expect(panel.getByRole('button', { name: 'הפקת קישור חדש', exact: true })).toBeVisible();
    await expect(panel.getByTestId('candidate-link')).toHaveCount(0);

    // Источник: S-11 «…אין מדובר בפסילה אלא בעניין טכני», AC5 «נתיב פנייה לגורם אנושי».
    const guest = await asUser('guest');
    await expectInactive(guest, link);
    await expect(guest.getByText(/פנו לצוות הגיוס של testim/)).toBeVisible();

    // Источник: треб.7 — статусы приглашения обновляются автоматически.
    await expect(await candidateRow(business, name)).toContainText('בוטל');
  });

  test(`«הארכת תוקף» после отмены: новая ссылка (другой токен), «עוד יומיים», «קישור נוצר»; старая — S-11, новая — «בוא נתחיל» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(3 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-45f435-E-${runStamp()}`;
    const first = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: отмена + продление, не удаляется` });
    const id = await candidateId(business, name);

    const panel = await openManage(business, id);
    await panel.getByRole('button', { name: 'ביטול הקישור', exact: true }).click();
    await confirmAction(business, 'ביטול הקישור', /\/rpc\/cancel_candidate_link/);
    await expect(panel.getByText('בוטל', { exact: true }).first()).toBeVisible();

    await panel.getByRole('button', { name: 'הארכת תוקף', exact: true }).click();
    await confirmAction(business, 'הארכת התוקף', /\/rpc\/[a-z_]*extend[a-z_]*/);
    // Источник: AC3 — «נוצר קישור תקף חדש והקישור הקודם נותר בלתי שמיש»; треб.1 — «תוקף … יומיים».
    await expect(panel.getByText('תוקף הקישור הוארך')).toBeVisible();
    await expect(panel.getByText(/קישור חדש בתוקף ליומיים, והקישור הקודם הפסיק לפעול/)).toBeVisible();
    await expect(panel.getByText('עוד יומיים')).toBeVisible();
    await expect(panel.getByText('קישור נוצר', { exact: true }).first()).toBeVisible();
    const second = await linkIn(panel);
    expect(new URL(second).pathname, 'продление выдаёт новый токен').not.toBe(new URL(first).pathname);

    const guest = await asUser('guest');
    await expectInactive(guest, first);
    await expectWelcome(guest, second);
  });

  test(`«הפקת קישור חדש» для активной ссылки: «הופק קישור חדש», новый токен, «עוד יומיים»; старая сразу S-11, новая — «בוא נתחיל» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(3 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-45f435-R-${runStamp()}`;
    const first = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: новая ссылка, не удаляется` });
    const id = await candidateId(business, name);

    const guest = await asUser('guest');
    await expectWelcome(guest, first); // до действия ссылка работает

    const panel = await openManage(business, id);
    await panel.getByRole('button', { name: 'הפקת קישור חדש', exact: true }).click();
    await confirmAction(business, 'הפקת קישור חדש', /\/rpc\/[a-z_]*(reissue|regenerate)[a-z_]*/);
    // Источник: треб.2 — «הפקת קישור חדש, כאשר קישור קודם מתבטל מיידית».
    await expect(panel.getByText('הופק קישור חדש').first()).toBeVisible();
    await expect(panel.getByText('עוד יומיים')).toBeVisible();
    const second = await linkIn(panel);
    expect(new URL(second).pathname).not.toBe(new URL(first).pathname);

    await expectInactive(guest, first);
    await expectWelcome(guest, second);
  });

  test(`подделанный/неизвестный токен → S-11 «לא מצאנו את הקישור…», ответ candidate_open_link not_found, данных кандидата нет @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const guest = await asUser('guest');
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
    const token = Array.from({ length: 43 }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join('');
    const open = guest.waitForResponse((r) => r.url().includes('/rpc/candidate_open_link'));
    // Источник: треб.4 — «הקישור אינו ניתן לניחוש»; S-11 — «פתיחת קישור … שאינו תקין».
    await expectInactive(guest, `/c/${token}`, S11.notFound);
    expect(await (await open).text()).toContain('not_found');
    await expect(guest.getByText('QA-')).toHaveCount(0);
  });
});
